INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王景崇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员。937年担任引进使，受命劝秘琼接受任命。史书记载他是邢州人。", "biography": null, "status": "draft", "id": "5f673eda-0daa-5174-926f-dca3e0982614"}, {"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "程渥", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "侯益的从事，与王景崇同乡且有旧交。948年王景崇考虑杀侯益时，程渥前去劝阻。《新五代史》记王景崇因此有所动摇，《宋史》却记王景崇怒斥并威胁程渥，两个版本分别保留。生卒年未载。", "biography": null, "status": "draft", "id": "8d5b5d20-39b9-5217-a05a-fd15d28a5f05"}, {"name": "刘承祐", "aliases": ["劉承祐", "后汉隐帝"], "era": "五代十国", "birth_year": 931, "death_year": null, "description": "刘知远第二子，母亲为李氏。《旧五代史》记他生于931年三月七日的邺都旧宅，曾任左卫大将军和大内都点检。948年二月先封周王，随后依据公布的遗制继承后汉皇位。《资治通鉴》记其即位时十八岁。", "biography": null, "status": "draft", "id": "96b54cac-772d-54e8-b2de-975b3be49e85"}, {"name": "张虔钊", "aliases": ["張虔釗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷274同光四年条所见人物：张虔钊。", "biography": null, "status": "draft", "id": "b4b03cda-5958-57ef-b1ca-a5c8e1fb4985"}, {"name": "史弘肇", "aliases": ["史宏肇"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "荥泽人，947年二月任刘知远的武节都指挥使，奉命在球场集合各军，宣布出兵日期。《旧五代史》亦有史宏肇的字形。生卒年暂未录入。", "biography": null, "status": "draft", "id": "c36d0d69-d2db-5ee8-9bf6-80791eb21dda"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "后汉任命王景崇兼凤翔巡检使", "start_year": 948, "end_year": 948, "time_original": "948年二月，具体日未载", "dynasty": "五代十国", "description": "后汉任命王景崇兼凤翔巡检使。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "06ffafd6-9eec-5cd0-a53c-13a7c1b5cc2b"}, {"title": "王景崇抵凤翔，分派禁军守城门", "start_year": 948, "end_year": 948, "time_original": "948年二月，具体日未载", "dynasty": "五代十国", "description": "王景崇抵凤翔，分派禁军守城门。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "25fa4268-1a86-5c86-90f4-2fbc6d7e08d4"}, {"title": "有人劝杀侯益，王景崇因新帝不知密旨而犹豫", "start_year": 948, "end_year": 948, "time_original": "948年二月，具体日未载", "dynasty": "五代十国", "description": "有人劝王景崇杀侯益。王景崇想到密旨由先帝刘知远单独授予，继位的刘承祐不知其事，担忧自己被认为擅杀，因此犹豫未决。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "6a627dd7-40d2-530e-b30a-e9aff252672f"}, {"title": "程渥劝王景崇不要杀侯益，两书记其结果不同", "start_year": 948, "end_year": 948, "time_original": "948年二月，具体日未载", "dynasty": "五代十国", "description": "侯益从事程渥与王景崇同乡且有旧交，前去劝王景崇不要杀侯益。《新五代史》记王景崇有所动摇，《宋史》却记他怒斥并威胁程渥，暂保留两种记载。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "f8d20f19-1056-56b8-82e7-6003f399824d"}, {"title": "侯益得知杀人议论，未告王景崇便离开", "start_year": 948, "end_year": 948, "time_original": "948年二月戊戌入朝之前，离开具体日未载", "dynasty": "五代十国", "description": "侯益得知杀人议论，未告王景崇便离开。", "phases": [], "location_name": "凤翔至后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "8f9cb3fe-62af-5ed4-aba5-65bf3e3b4a79"}, {"title": "王景崇后悔未杀侯益，责骂自己", "start_year": 948, "end_year": 948, "time_original": "948年二月侯益离去之后，具体日未载", "dynasty": "五代十国", "description": "王景崇后悔未杀侯益，责骂自己。", "phases": [], "location_name": "凤翔", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e80ac1e0-420a-5a9b-aeb7-b4fe18210d82"}, {"title": "侯益入朝，声称召蜀军是为诱来杀掉，刘承祐笑之", "start_year": 948, "end_year": 948, "time_original": "948年二月戊戌", "dynasty": "五代十国", "description": "侯益入朝，刘承祐问他为何召蜀军。侯益回答说是想诱来杀掉，刘承祐听后发笑。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "12735c9e-9b23-5e87-8a47-0e5c7b5d0de4"}, {"title": "张虔钊因出兵无功而懊恼", "start_year": 948, "end_year": 948, "time_original": "948年二月癸卯之前，具体日未载", "dynasty": "五代十国", "description": "张虔钊因出兵无功而懊恼。", "phases": [], "location_name": "蜀军撤回途中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "b5938769-1585-5cc3-9583-3761233b8974"}, {"title": "张虔钊到兴州，惭愤去世", "start_year": 948, "end_year": 948, "time_original": "948年二月癸卯", "dynasty": "五代十国", "description": "张虔钊到兴州，惭愤去世。", "phases": [], "location_name": "兴州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "96feaea6-b267-5419-9a85-3efe903aef9f"}, {"title": "史弘肇的母亲去世", "start_year": 948, "end_year": 948, "time_original": "948年二月末相关叙述，具体日未载", "dynasty": "五代十国", "description": "史弘肇的母亲去世。", "phases": [], "location_name": "后汉", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "320e0bda-8cb1-5cc6-b0b6-6e3dc2fac0bb"}, {"title": "史弘肇遭母丧后不到几天，重新参加朝会", "start_year": 948, "end_year": 948, "time_original": "948年母丧后数日内，具体日未载", "dynasty": "五代十国", "description": "史弘肇遭母丧后不到几天，重新参加朝会。", "phases": [], "location_name": "后汉朝廷", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "ecf4d08e-5365-5898-b2c8-924083686682"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

